{
  "passageId": "consciousness-cognition-na",
  "items": [
    {
      "id": "R1",
      "type": "CONCESSION",
      "otherName": "",
      "reason": "동일한 내가 몸으로서는 사물과 같은 세계에 속하면서 의식으로서는 다른 세계에 속한다는 양면성을 제시한다."
    },
    {
      "id": "R2",
      "type": "ELABORATION",
      "otherName": "",
      "reason": "지각 분석에서 직면한다는 두 가지 사실의 내용을 몸과 의식의 소속 세계로 구체화한다."
    },
    {
      "id": "R3",
      "type": "DEVELOPMENT",
      "otherName": "",
      "reason": "지각에서 드러나는 몸과 의식의 관계를 제시한 뒤 이를 설명하는 객관주의 철학의 입장으로 논의를 옮긴다."
    },
    {
      "id": "R4",
      "type": "APPLICATION",
      "otherName": "",
      "reason": "의식을 물질로 환원하는 일반적 입장을 지각 현상에 적용하여 지각을 물질적 반응으로 설명한다."
    },
    {
      "id": "R5",
      "type": "APPLICATION",
      "otherName": "",
      "reason": "의식을 독자적 실체로 보는 일반적 입장을 지각 현상에 적용하여 지각을 의식의 판단으로 설명한다."
    },
    {
      "id": "R6",
      "type": "VIEW_DIFFERENCE",
      "otherName": "",
      "reason": "객관주의 철학의 두 입장이 지각을 각각 물질적 반응과 의식의 판단으로 다르게 이해함을 나란히 제시한다."
    },
    {
      "id": "R7",
      "type": "VIEW_AGREEMENT",
      "otherName": "",
      "reason": "물질적 반응으로 지각을 설명하는 입장이 다른 객관주의 입장과 주체·대상의 선행적 분리라는 전제를 공유함을 밝힌다."
    },
    {
      "id": "R8",
      "type": "VIEW_AGREEMENT",
      "otherName": "",
      "reason": "의식의 판단으로 지각을 설명하는 입장이 다른 객관주의 입장과 주체·대상의 선행적 분리라는 전제를 공유함을 밝힌다."
    },
    {
      "id": "R9",
      "type": "DEFINITION",
      "otherName": "",
      "reason": "주체와 대상의 분리를 전제한다는 말의 뜻을 지각 이전에 양자가 확정되어 각각 존재한다는 말로 풀어 쓴다."
    },
    {
      "id": "R10",
      "type": "CRITIQUE",
      "otherName": "",
      "reason": "지각이 독립적 주체와 대상에 앞선다는 주장으로 객관주의 철학의 공통 전제를 부정한다."
    },
    {
      "id": "R11",
      "type": "PARALLEL",
      "otherName": "",
      "reason": "손을 만지는 작용과 손이 만져지는 작용을 동시에 이루어지는 같은 층위의 두 작용으로 나란히 제시한다."
    },
    {
      "id": "R12",
      "type": "ELABORATION",
      "otherName": "",
      "reason": "손을 만지면서 동시에 만져지는 구체적 사례가 지각이라는 얽힘의 체험을 보여 준다."
    },
    {
      "id": "R13",
      "type": "ELABORATION",
      "otherName": "",
      "reason": "만지면서 만져지는 사례를 감각하는 것이 동시에 감각되는 얽힘의 일반적 성질로 풀어 설명한다."
    },
    {
      "id": "R14",
      "type": "CAUSE",
      "otherName": "",
      "reason": "지문은 감각하는 것과 감각되는 것이 얽히는 작용을 통해 나와 대상의 구분이 생긴다고 설명한다."
    },
    {
      "id": "R15",
      "type": "ELABORATION",
      "otherName": "",
      "reason": "얽힘의 순간에 나와 대상을 구분하는 체험을 주체와 대상의 분리·확정에 관한 일반적 설명으로 확장한다."
    },
    {
      "id": "R16",
      "type": "DEFINITION",
      "otherName": "",
      "reason": "지각이 주체와 대상의 독립적 존재에 앞선다는 내용을 주체와 대상이 지각 이후에 확정된다는 말로 재진술한다."
    },
    {
      "id": "R17",
      "type": "CRITIQUE",
      "otherName": "",
      "reason": "주체와 대상이 지각 이후에 확정된다는 주장으로 지각 이전에 이미 확정되어 있다는 객관주의의 전제를 반박한다."
    },
    {
      "id": "R18",
      "type": "GROUNDS",
      "otherName": "",
      "reason": "주체와 대상이 지각이라는 얽힘 이후에 확정된다는 설명을 근거로 지각과 감각이 구분되지 않는다는 결론을 이끈다."
    },
    {
      "id": "R19",
      "type": "CRITIQUE",
      "otherName": "",
      "reason": "지각은 물질적 반응이 아니라 몸의 체험이라는 주장으로 물질 환원적 입장의 지각 규정을 명시적으로 부정한다."
    },
    {
      "id": "R20",
      "type": "CRITIQUE",
      "otherName": "",
      "reason": "지각은 의식의 판단이 아니라 몸의 체험이라는 주장으로 의식을 독자적 실체로 보는 입장의 지각 규정을 부정한다."
    },
    {
      "id": "R21",
      "type": "GROUNDS",
      "otherName": "",
      "reason": "감각하는 것과 감각되는 것이 얽히는 체험이라는 앞선 설명을 바탕으로 지각을 내 몸의 체험이라고 최종 규정한다."
    },
    {
      "id": "R22",
      "type": "ELABORATION",
      "otherName": "",
      "reason": "지각이 몸의 체험이라는 규정을 지각의 성립이 전적으로 나의 몸에 의한다는 설명으로 구체화한다."
    }
  ]
}

